import manifest from "./photos.json";

/** One photo, already sized for the web. w/h are the real proportions, so it is shown uncropped. */
export interface Photo {
  src: string;
  full: string;
  w: number;
  h: number;
}

// Generated by scripts/photos.py from scripts/photo-sort.json. To add or move photos:
// put the file in assets-src/photos, list it under a section in photo-sort.json, run the script.
export const winsPhotos: Photo[] = manifest.wins;
export const campusPhotos: Photo[] = manifest.campus;
export const hobbyPhotos: Photo[] = manifest.hobbies;
